fn second(v: Vec<Int>) -> Option<Int> {
    let x = get(v, 1)?
    Some(x + 1)
}

fn main() {
    print(second(vec(7, 8, 9)))
    print(second(vec(7)))
    print(second(vec()))
}

fn second(v: Vec<Int>) -> Option<Int> {
    let x = get(v, 0)?
    Some(x + 1)
}

